# identity-center-grupos.tf -- grupos por area no Identity Store do
# IAM Identity Center, e o metadado de grupo que o filtro de recuperacao
# depende. Pressupoe Identity Center ja habilitado na organizacao (fora
# do escopo deste laboratorio -- e' feito uma vez, no nivel da conta de
# gerenciamento).

data "aws_ssoadmin_instances" "atual" {}

locals {
  identity_store_id = tolist(data.aws_ssoadmin_instances.atual.identity_store_ids)[0]
  areas             = ["rh", "financeiro", "juridico", "engenharia", "diretoria"]
}

resource "aws_identitystore_group" "area" {
  for_each          = toset(local.areas)
  identity_store_id = local.identity_store_id
  display_name      = "copiloto-${each.value}"
  description       = "Grupo de acesso do copiloto interno para a area ${each.value}"
}

# Exemplo: Marina (engenharia) e' membro so do proprio grupo -- a
# filiacao real vem sincronizada do diretorio corporativo (Okta/AD),
# nao cadastrada a mao; este recurso ilustra o formato.
resource "aws_identitystore_group_membership" "exemplo_marina" {
  identity_store_id = local.identity_store_id
  group_id          = aws_identitystore_group.area["engenharia"].group_id
  member_id         = data.aws_identitystore_user.marina.user_id
}

data "aws_identitystore_user" "marina" {
  identity_store_id = local.identity_store_id
  alternate_identifier {
    unique_attribute {
      attribute_path  = "UserName"
      attribute_value = "marina@cadencia.exemplo"
    }
  }
}

# Metadado de exemplo: documento restrito a financeiro E diretoria --
# lista, nao valor unico, porque um documento pode ser legitimamente
# visivel a mais de um grupo.
resource "aws_s3_object" "exemplo_provisao_reembolso" {
  bucket = aws_s3_bucket.documentos_internos.id
  key    = "financeiro/provisao-reembolso-departamental-q3.xlsx"
  source = "docs/provisao-reembolso-q3.xlsx"
}

resource "aws_s3_object" "exemplo_provisao_reembolso_metadado" {
  bucket  = aws_s3_bucket.documentos_internos.id
  key     = "financeiro/provisao-reembolso-departamental-q3.xlsx.metadata.json"
  content = jsonencode({
    metadataAttributes = {
      grupos_permitidos = {
        value                = { type = "STRING_LIST", stringListValue = ["financeiro", "diretoria"] }
        includeForEmbedding  = false
      }
    }
  })
}

# Documento publico: grupo 'geral', que todo funcionario tem por padrao.
resource "aws_s3_object" "exemplo_politica_reembolso_equipamento_metadado" {
  bucket  = aws_s3_bucket.documentos_internos.id
  key     = "rh/politica-reembolso-equipamento.pdf.metadata.json"
  content = jsonencode({
    metadataAttributes = {
      grupos_permitidos = {
