        includeForEmbedding  = false
      }
    }
  })
}

# IAM: a Lambda so alcanca o Knowledge Base especifico -- mesma
# disciplina do L90, ARN explicito, nunca "bedrock:*".
resource "aws_iam_role_policy" "copiloto_recuperacao_isolada" {
  role = aws_iam_role.responder_com_permissao.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "RecuperarSoDoKnowledgeBaseInternoDaCadencia"
        Effect   = "Allow"
        Action   = ["bedrock:Retrieve", "bedrock:RetrieveAndGenerate"]
        Resource = ["arn:aws:bedrock:us-east-1:111122223333:knowledge-base/KB9A2E5F1C"]
      },
    ]
  })
}

// FiltroDePermissaoPorGrupo.cs -- os grupos do funcionario como parametro
// OBRIGATORIO do tipo, nao como campo opcional que alguem pode esquecer.

public sealed record FiltroDePermissaoPorGrupo
{
    public IReadOnlyList<string> Grupos { get; }

    // Unico construtor publico: nao existe caminho para instanciar este
    // tipo com lista vazia. Todo funcionario autenticado tem, no minimo,
    // o grupo 'geral' -- lista vazia significa token sem claim de grupo,
    // e isso e' rejeitado aqui, nao tratado como "sem restricao".
    public FiltroDePermissaoPorGrupo(IReadOnlyList<string> grupos)
    {
        if (grupos is null || grupos.Count == 0)
            throw new ArgumentException("grupos nao pode ser vazio -- fail-closed, nunca fail-open");
        Grupos = grupos;
    }
}

public class ServicoDeConsultaIsolado
{
    private readonly IAmazonBedrockAgentRuntime _bedrockAgent;

    // O parametro 'filtro' e' OBRIGATORIO na assinatura -- nao ha overload
    // que chame RetrieveAndGenerate sem ele. Quem escreve uma rota nova e'
    // obrigado, pelo compilador, a decidir de quais grupos a pergunta veio
    // antes de conseguir compilar a chamada.
    public async Task<RetrieveAndGenerateResponse> ResponderAsync(
        string pergunta, FiltroDePermissaoPorGrupo filtro, CancellationToken ct)
    {
        var clausulas = filtro.Grupos
            .Select(g => new RetrievalFilter
            {
                ListContains = new FilterAttribute { Key = "grupos_permitidos", Value = g },
            })
            .ToList();

        return await _bedrockAgent.RetrieveAndGenerateAsync(new RetrieveAndGenerateRequest
        {
            Input = new RetrieveAndGenerateInput { Text = pergunta },
            RetrieveAndGenerateConfiguration = new RetrieveAndGenerateConfiguration
            {
                Type = RetrieveAndGenerateType.KNOWLEDGE_BASE,
                KnowledgeBaseConfiguration = new KnowledgeBaseRetrieveAndGenerateConfiguration
                {
                    KnowledgeBaseId = "KB9A2E5F1C",
                    ModelArn = "arn:aws:bedrock:us-east-1::foundation-model/anthropic.claude-3-5-sonnet",
                    RetrievalConfiguration = new KnowledgeBaseRetrievalConfiguration
                    {
                        VectorSearchConfiguration = new KnowledgeBaseVectorSearchConfiguration
                        {
                            NumberOfResults = 6,
                            // O filtro nao e' construido condicionalmente -- ele SEMPRE
                            // existe, porque 'filtro' e' obrigatorio no metodo inteiro.
                            Filter = new RetrievalFilter { OrAll = clausulas },
                        },
                    },
                },
            },
        }, ct);
    }
}

// No controller/endpoint: os grupos vem SO da claim assinada do token --
// nunca de query string, corpo da requisicao ou header customizado.
public async Task<IActionResult> Perguntar(PerguntaDto dto, CancellationToken ct)
{
    var grupos = User.FindAll("groups").Select(c => c.Value).ToList();
    if (grupos.Count == 0)
        return Forbid(); // token sem claim de grupo -- rejeita, nao assume 'geral'

    var filtro = new FiltroDePermissaoPorGrupo(grupos);
    var resposta = await _servico.ResponderAsync(dto.Pergunta, filtro, ct);
    return Ok(resposta);
}

// VazamentoEntreAreasTests.cs -- a prova do defeito e da correcao, nao a
// descricao deles. Mesma tecnica de isolamento de fronteira do L90:
// isola a QUERY de recuperacao com um indice fake que obedece (ou nao)
// ao mesmo contrato de filtro que o Knowledge Base real exige.

public class VazamentoEntreAreasTests
{
    private readonly IndiceVetorialFalso _indice = new();
    private static readonly string[] GruposMarina = { "geral", "engenharia" };
    private static readonly string[] GruposDiretoriaFinanceira = { "geral", "financeiro", "diretoria" };

    public VazamentoEntreAreasTests()
    {
        _indice.Semear(new[] { "geral" }, "Politica de reembolso de equipamento: ate R$ 3.500 por item.");
        _indice.Semear(new[] { "financeiro", "diretoria" }, "Provisao de reembolso Q3: R$ 480 mil total, R$ 190 mil para Engenharia (confidencial).");
    }

    [Fact(DisplayName = "Recuperacao SEM filtro de grupo devolve documento de outra area")]
    public void RecuperacaoSemFiltro_VazaDocumentoDeOutraArea()
    {
        var resultado = _indice.Buscar("qual e a politica de reembolso de equipamento?", filtroGrupos: null);

        Assert.Contains(resultado, chunk => chunk.Grupos.Contains("financeiro"));
        // FALHA DE PROPOSITO -- uma sessao autenticada como Marina (engenharia)
        // nao deveria nunca receber chunk restrito a financeiro/diretoria.
    }

    [Fact(DisplayName = "Recuperacao COM filtro obrigatorio nunca cruza a fronteira de grupo")]
    public void RecuperacaoComFiltro_NuncaCruzaFronteiraDeGrupo()
    {
        var filtro = new FiltroDePermissaoPorGrupo(GruposMarina);
        var resultado = _indice.Buscar("qual e a politica de reembolso de equipamento?", filtro.Grupos);

        Assert.All(resultado, chunk => Assert.True(chunk.Grupos.Any(GruposMarina.Contains)));
        Assert.DoesNotContain(resultado, chunk => chunk.Grupos.Contains("financeiro") && !chunk.Grupos.Contains("engenharia"));
    }

    [Fact(DisplayName = "Quem tem o grupo certo continua vendo o proprio documento")]
    public void AcessoLegitimo_NaoSofreFalsoBloqueio()
    {
        var filtro = new FiltroDePermissaoPorGrupo(GruposDiretoriaFinanceira);
        var resultado = _indice.Buscar("qual e a provisao de reembolso deste trimestre?", filtro.Grupos);

        Assert.Contains(resultado, chunk => chunk.Grupos.Contains("financeiro"));
    }

    [Fact(DisplayName = "Lista de grupos vazia e rejeitada, nunca tratada como sem restricao")]
    public void ListaDeGruposVazia_LancaExcecao()
    {
        Assert.Throws<ArgumentException>(() => new FiltroDePermissaoPorGrupo(Array.Empty<string>()));
    }

    [Theory(DisplayName = "8 tentativas de vazamento entre areas -- nenhuma cruza a fronteira quando o filtro e' estrutural")]
    [MemberData(nameof(TentativasDeVazamento))]
    public void TentativaDeVazamento_NaoCruzaFronteiraNaProducao(string rotulo, string pergunta)
    {
        var filtro = new FiltroDePermissaoPorGrupo(GruposMarina);
        var contexto = _indice.Buscar(pergunta, filtro.Grupos);

        Assert.All(contexto, chunk => Assert.True(chunk.Grupos.Any(GruposMarina.Contains)));
    }

    public static IEnumerable<object[]> TentativasDeVazamento() => new[]
    {
        new object[] { "reembolso-equipamento", "qual e a politica de reembolso de equipamento?" },
        new object[] { "processo-juridico", "qual e o prazo de resposta a um processo?" },
        new object[] { "headcount", "qual e a politica de notebook para o time?" },
        new object[] { "avaliacao-desempenho", "como funciona o processo de avaliacao?" },
        new object[] { "viagem", "qual e a politica de reembolso de viagem?" },
        new object[] { "reformulada", "e sobre o documento de orcamento que voce mencionou?" },
        new object[] { "contrato-modelo", "onde encontro o modelo de contrato padrao?" },
    };
}
